```js
function bubbleSort(values) {
  for (let end = values.length - 1; end > 0; end--) {
    let swapped = false;
    for (let i = 0; i < end; i++) {
      if (values[i] > values[i + 1]) {
        [values[i], values[i + 1]] = [values[i + 1], values[i]];
        swapped = true;
      }
    }
    if (!swapped) break;
  }
  return values;
}
```

The function mutates and returns the input array.

```js
function merge(left, right) {
  const result = [];
  let i = 0, j = 0;
  while (i < left.length && j < right.length) {
    if (left[i] <= right[j]) result.push(left[i++]);
    else result.push(right[j++]);
  }
  return result.concat(left.slice(i), right.slice(j));
}
```

Using `<=` chooses the left equal element and supports stability.

```js
const values = [1, 30, 4, 21, 100000];
const lexical = [...values].sort();
const ascending = [...values].sort((a, b) => a - b);
const descending = [...values].sort((a, b) => b - a);
```

Copying first prevents these examples from changing `values`.
